'use client'

/**
 * License activation page — shown BEFORE login/register.
 *
 * The user pastes their GF2.xxx.xxx.xxx token (generated by keygen.py).
 * Calls POST /api/license/activate — ALL crypto happens server-side.
 * On success the server sets HttpOnly-ish cookies; we just redirect.
 */

import { useState, FormEvent, useEffect } from 'react'
import { CLIENT_BRAND } from '@/config/brand.client'
import { useRouter } from 'next/navigation'
import {
  ShieldCheck, ShieldX, Loader2, Key, ArrowRight, Lock, Crown, Info
} from 'lucide-react'
import { cn } from '@/lib/utils'
import { GarageFlowIcon } from '@/components/GarageFlowLogo'
import { getOrCreateInstallId } from '@/lib/pwa-install-id'

const LICENSE_TYPE_LABELS: Record<string, string> = {
  admin:      'Administrateur',
  enterprise: 'Enterprise',
  premium:    'Premium',
  trial:      'Essai',
}

export default function LicensePage() {
  const router = useRouter()

  const [token,   setToken]   = useState('')
  const [status,  setStatus]  = useState<'idle' | 'checking' | 'ok' | 'error'>('idle')
  const [message, setMessage] = useState('')
  const [licType, setLicType] = useState<string>('')
  const [expiry,  setExpiry]  = useState<string>('')

  // If already licensed, skip straight to the right destination
  useEffect(() => {
    const c = Object.fromEntries(
      document.cookie.split(';').map(s => {
        const [k, ...v] = s.trim().split('=')
        return [k, v.join('=')]
      })
    )
    if (c['gf_license_type'] === 'admin') { router.replace('/admin/licenses'); return }
    if (c['gf_license_validated'] === '1') { router.replace('/login') }
  }, [router])

  async function handleSubmit(e: FormEvent) {
    e.preventDefault()
    setStatus('checking')
    setMessage('')

    try {
      // Identifiant d'installation PWA : consomme un siège comme un appareil.
      const installId = getOrCreateInstallId()
      const res  = await fetch('/api/license/activate', {
        method:  'POST',
        headers: { 'Content-Type': 'application/json' },
        body:    JSON.stringify({ license: token.trim(), ...(installId ? { installId } : {}) }),
      })
      const data = await res.json() as {
        ok:           boolean
        isAdmin?:     boolean
        licenseType?: string
        expiryAt?:    string
        reason?:      string
      }

      if (!data.ok) {
        setStatus('error')
        setMessage(data.reason ?? 'Licence invalide')
        return
      }

      const typ    = data.licenseType ?? 'premium'
      const expYear = data.expiryAt ? new Date(data.expiryAt).getFullYear() : '?'
      setLicType(typ)
      setExpiry(String(expYear))
      setStatus('ok')

      if (typ === 'admin') {
        setMessage('Clé administrateur — accès au panneau de gestion')
        setTimeout(() => router.push('/admin/licenses'), 1600)
      } else {
        setMessage(`Licence ${LICENSE_TYPE_LABELS[typ] ?? typ} activée · Valide jusqu'en ${expYear}`)
        setTimeout(() => router.push('/login'), 1600)
      }
    } catch {
      setStatus('error')
      setMessage('Erreur réseau — vérifiez votre connexion')
    }
  }

  const isAdmin   = licType === 'admin'
  const tokenReady = token.trim().startsWith('GF2.') && token.trim().split('.').length === 4

  return (
    <div className="min-h-screen bg-[#0a0f1e] flex items-center justify-center p-4 relative overflow-hidden">
      {/* Ambient glows */}
      <div className="absolute inset-0 pointer-events-none">
        <div className="absolute top-1/4 left-1/3 w-96 h-96 bg-blue-600/8 rounded-full blur-3xl" />
        <div className="absolute bottom-1/4 right-1/4 w-80 h-80 bg-orange-500/5 rounded-full blur-3xl" />
        <div className="absolute top-0 left-0 w-64 h-64 bg-indigo-900/10 rounded-full blur-3xl" />
      </div>

      <div className="relative w-full max-w-lg">
        {/* Branding */}
        <div className="text-center mb-8">
          <div className="flex justify-center mb-4">
            <div className="relative">
              <GarageFlowIcon size={80} />
              <div className="absolute inset-0 rounded-[22px] ring-1 ring-blue-500/20 shadow-xl shadow-blue-500/20" />
            </div>
          </div>
          <h1 className="text-3xl font-black text-white tracking-tight">
            Garage<span className="text-blue-400">Flow</span>
          </h1>
          <p className="text-slate-500 text-xs mt-1.5 tracking-[0.2em] uppercase font-medium">
            Le planning intelligent pour garages
          </p>
          <div className="flex items-center justify-center gap-2 mt-2">
            <div className="h-px w-10 bg-orange-500/50" />
            <span className="text-orange-400 text-[10px] font-black tracking-[0.25em] uppercase">Pro</span>
            <div className="h-px w-10 bg-orange-500/50" />
          </div>
        </div>

        {/* Card */}
        <div className="bg-[#111827]/95 backdrop-blur-xl border border-white/[0.08] rounded-2xl p-7 shadow-2xl shadow-black/60">
          {/* Header */}
          <div className="flex items-center gap-3 mb-5 pb-5 border-b border-white/[0.06]">
            <div className="w-10 h-10 rounded-xl bg-blue-600/20 flex items-center justify-center">
              <Lock className="w-5 h-5 text-blue-400" />
            </div>
            <div>
              <h2 className="text-base font-bold text-white">Activation du logiciel</h2>
              <p className="text-xs text-slate-500 mt-0.5">
                Collez votre clé de licence pour accéder à {CLIENT_BRAND.productName}
              </p>
            </div>
          </div>

          {/* Success */}
          {status === 'ok' ? (
            <div className="flex flex-col items-center gap-3 py-4">
              <div className={cn('w-14 h-14 rounded-full flex items-center justify-center',
                isAdmin ? 'bg-amber-500/20' : 'bg-emerald-500/20')}>
                {isAdmin
                  ? <Crown className="w-7 h-7 text-amber-400" />
                  : <ShieldCheck className="w-7 h-7 text-emerald-400" />}
              </div>
              <div className="text-center">
                <p className={cn('font-bold text-sm', isAdmin ? 'text-amber-400' : 'text-emerald-400')}>
                  {message}
                </p>
                <p className="text-slate-500 text-xs mt-1">
                  {isAdmin ? 'Redirection vers le panneau admin…' : 'Redirection vers la connexion…'}
                </p>
              </div>
              <Loader2 className={cn('w-4 h-4 animate-spin mt-1',
                isAdmin ? 'text-amber-500/60' : 'text-emerald-500/60')} />
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="space-y-4">
              {/* Token textarea */}
              <div>
                <label className="block text-xs font-semibold text-slate-400 mb-1.5 tracking-wide">
                  Clé de licence
                </label>
                <div className="relative">
                  <Key className="absolute left-3 top-3 w-4 h-4 text-slate-600" />
                  <textarea
                    value={token}
                    onChange={e => {
                      setToken(e.target.value)
                      if (status === 'error') setStatus('idle')
                    }}
                    rows={3}
                    autoFocus
                    spellCheck={false}
                    autoComplete="off"
                    placeholder={'GF2.eyJ...'}
                    className={cn(
                      'w-full pl-9 pr-4 py-2.5 rounded-xl text-xs font-mono resize-none transition-all focus:outline-none',
                      'bg-white/[0.05] border text-slate-300 placeholder-slate-700',
                      status === 'error'
                        ? 'border-red-500/50 focus:ring-2 focus:ring-red-500/30'
                        : 'border-white/[0.10] focus:ring-2 focus:ring-blue-500/40 focus:border-blue-500/30'
                    )}
                  />
                </div>

                {/* Format hint */}
                <div className="flex items-start gap-1.5 mt-1.5">
                  <Info className="w-3 h-3 text-slate-700 mt-0.5 flex-shrink-0" />
                  <p className="text-[10px] text-slate-700">
                    Format: <span className="font-mono text-slate-600">GF2.&lt;header&gt;.&lt;payload&gt;.&lt;signature&gt;</span>
                    {' '}— fourni par votre revendeur ou généré par{' '}
                    <span className="text-slate-500">python scripts/keygen.py</span>
                  </p>
                </div>
              </div>

              {/* Error */}
              {status === 'error' && (
                <div className="flex items-start gap-2 p-3 bg-red-500/10 border border-red-500/25 rounded-xl">
                  <ShieldX className="w-4 h-4 text-red-400 flex-shrink-0 mt-0.5" />
                  <p className="text-red-400 text-xs">{message}</p>
                </div>
              )}

              {/* Submit */}
              <button
                type="submit"
                disabled={!tokenReady || status === 'checking'}
                className={cn(
                  'w-full py-3 px-4 rounded-xl font-semibold text-sm transition-all flex items-center justify-center gap-2',
                  !tokenReady || status === 'checking'
                    ? 'bg-blue-600/20 text-blue-400/40 cursor-not-allowed'
                    : 'bg-blue-600 text-white hover:bg-blue-500 shadow-lg shadow-blue-600/25 active:scale-[0.98]'
                )}
              >
                {status === 'checking' ? (
                  <><Loader2 className="w-4 h-4 animate-spin" />Vérification en cours…</>
                ) : (
                  <><ShieldCheck className="w-4 h-4" />Activer {CLIENT_BRAND.productName}<ArrowRight className="w-4 h-4" /></>
                )}
              </button>
            </form>
          )}

          {/* Help */}
          <div className="mt-5 pt-4 border-t border-white/[0.06] text-center">
            <p className="text-xs text-slate-600">
              Pas encore de licence ?{' '}
              <a href="mailto:contact@garageflow.fr"
                className="text-blue-500 hover:text-blue-400 font-medium transition-colors">
                Contactez-nous
              </a>
            </p>
          </div>
        </div>

        <p className="mt-4 text-center text-[10px] text-slate-800">
          © {new Date().getFullYear()} {CLIENT_BRAND.productName} · Tous droits réservés
        </p>
      </div>
    </div>
  )
}
